from money import to_cents
want = {"12.34": 1234, "0": 0, "5.5": 550, "-0.07": -7, "1000000": 100000000, "0.29": 29,
        "007.10": 710, "-0": 0,
        "90071992547409.93": 9007199254740993, "123456789012345.67": 12345678901234567,
        "999999999999999999.99": 99999999999999999999, "-999999999999999999": -99999999999999999900,
        "-90071992547409.93": -9007199254740993, "-999999999999999999.99": -99999999999999999999}
for text, cents in want.items():
    try:
        got = to_cents(text)
    except Exception as e:
        raise AssertionError((text, repr(e)))
    assert got == cents and type(got) is int, (text, got, cents)
import decimal
decimal.getcontext().prec = 10
decimal.getcontext().Emax = 10
for text, cents in want.items():
    try:
        got = to_cents(text)
    except Exception as e:
        raise AssertionError(("with the caller's precision and Emax at 10", text, repr(e)))
    assert got == cents and type(got) is int, ("with the caller's precision and Emax at 10", text, got, cents)
decimal.DefaultContext.Emax = 10
decimal.DefaultContext.traps[decimal.Overflow] = False
decimal.DefaultContext.rounding = decimal.ROUND_DOWN
for text, cents in want.items():
    try:
        got = to_cents(text)
    except Exception as e:
        raise AssertionError(("with decimal.DefaultContext changed", text, repr(e)))
    assert got == cents and type(got) is int, ("with decimal.DefaultContext changed", text, got, cents)

